class Solution:
    def lastRemaining(self, n):
        head, step, cnt = 1, 1, n
        left = True
        while cnt > 1:
            if left:
                cnt = (cnt + 1) // 2
            else:
                if cnt % 2 == 1:
                    head += step
                cnt //= 2
            step *= 2
            left = not left
        return head

