class Solution {
public:
    long long lastRemaining(long long n) {
        long long head = 1, step = 1, cnt = n;
        bool left = true;
        while (cnt > 1) {
            if (left) {
                cnt = (cnt + 1) / 2;
            } else {
                if (cnt % 2 == 1) head += step;
                cnt /= 2;
            }
            step *= 2;
            left = !left;
        }
        return head;
    }
};

