var lastRemaining = function(n) {
    let head = 1, step = 1, cnt = n, left = true;
    while (cnt > 1) {
        if (left) {
            cnt = Math.ceil(cnt / 2);
        } else {
            if (cnt % 2 === 1) head += step;
            cnt = Math.floor(cnt / 2);
        }
        step *= 2;
        left = !left;
    }
    return head;
};

